-- Premium speaking/writing tasks and bilingual topic choices for the 14 new lessons.
-- Forward-only extension generated from scripts/premium-topic-manifest.mjs.
-- Requires migration 020 to have inserted all referenced review_lessons rows.

do $requirements$
declare
  lesson_count integer;
  active_teacher_count integer;
begin
  select count(*) into lesson_count
  from public.review_lessons
  where slug in ('july-30-part-1', 'july-30-part-2', 'august-02', 'august-03', 'august-09', 'august-10-part-1', 'august-10-part-2', 'august-16-part-1', 'august-16-part-2', 'august-17-part-1', 'august-17-part-2', 'august-23', 'august-24', 'august-25');

  if lesson_count <> 14 then
    raise exception 'Premium task prerequisites incomplete: expected 14 lessons from migration 020, found %.', lesson_count;
  end if;

  select count(*) into active_teacher_count
  from public.review_teachers
  where active;

  if active_teacher_count < 1 then
    raise exception 'Premium task prerequisites incomplete: an active teacher is required.';
  end if;
end;
$requirements$;

with source(slug, topics) as (
  values
    ('july-30-part-1', '[{"key":"future-hope","title_en":"A hope you can work toward","title_ja":"実現に近づける希望","description_en":"A realistic hope for the future and one step you can take toward it.","description_ja":"将来への現実的な希望と、その実現に向けてできる一歩","speaking_prompt_en":"Speak for 60–90 seconds about a realistic hope for the future and one step you can take toward it. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"将来への現実的な希望と、その実現に向けてできる一歩について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a realistic hope for the future and one step you can take toward it. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"将来への現実的な希望と、その実現に向けてできる一歩について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I hope I can …","I hope everything goes well.","I hope we can …"],"vocabulary":["hope","possibility","future","progress"]},{"key":"present-wish","title_en":"What you wish were different","title_ja":"今と違ってほしいこと","description_en":"Something you wish were different now, such as your location, free time or ability.","description_ja":"場所・自由時間・能力など、今と違ってほしいと思うこと","speaking_prompt_en":"Speak for 60–90 seconds about something you wish were different now, such as your location, free time or ability. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"場所・自由時間・能力など、今と違ってほしいと思うことについて60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about something you wish were different now, such as your location, free time or ability. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"場所・自由時間・能力など、今と違ってほしいと思うことについて100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I wish I were …","I wish I had more …","I wish I could …"],"vocabulary":["wish","reality","ability","confidence"]},{"key":"past-regret","title_en":"A regret and its lesson","title_ja":"後悔とそこからの学び","description_en":"A past action you wish you had or had not taken and what you learned from it.","description_ja":"すればよかった、またはしなければよかった過去の行動と、そこから学んだこと","speaking_prompt_en":"Speak for 60–90 seconds about a past action you wish you had or had not taken and what you learned from it. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"すればよかった、またはしなければよかった過去の行動と、そこから学んだことについて60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a past action you wish you had or had not taken and what you learned from it. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"すればよかった、またはしなければよかった過去の行動と、そこから学んだことについて100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Stretch","phrases":["I wish I had …","I wish I hadn’t …","Since then, I’ve …"],"vocabulary":["regret","hindsight","consequence","lesson"]}]'::jsonb),
    ('july-30-part-2', '[{"key":"recent-progress","title_en":"What you have done recently","title_ja":"最近できたこと","description_en":"Things you have already, just or not yet completed and why they matter now.","description_ja":"already・just・yetを使って伝える最近の完了・未完了と、今とのつながり","speaking_prompt_en":"Speak for 60–90 seconds about things you have already, just or not yet completed and why they matter now. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"already・just・yetを使って伝える最近の完了・未完了と、今とのつながりについて60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about things you have already, just or not yet completed and why they matter now. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"already・just・yetを使って伝える最近の完了・未完了と、今とのつながりについて100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I have already …","I’ve just …","I haven’t … yet."],"vocabulary":["already","just","yet","recently"]},{"key":"continuing-since","title_en":"A change that continues today","title_ja":"今まで続いている変化","description_en":"A situation that began in the past and still continues today.","description_ja":"過去に始まり、現在まで続いている生活・仕事・学習の状況","speaking_prompt_en":"Speak for 60–90 seconds about a situation that began in the past and still continues today. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"過去に始まり、現在まで続いている生活・仕事・学習の状況について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a situation that began in the past and still continues today. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"過去に始まり、現在まで続いている生活・仕事・学習の状況について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I have … since …","I have … for …","It has changed …"],"vocabulary":["since","duration","continue","present"]},{"key":"before-another-past","title_en":"Two moments in the past","title_ja":"過去の二つの時点","description_en":"A story with two past events that makes clear which one happened first.","description_ja":"二つの過去の出来事について、どちらが先だったかを明確にする話","speaking_prompt_en":"Speak for 60–90 seconds about a story with two past events that makes clear which one happened first. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"二つの過去の出来事について、どちらが先だったかを明確にする話について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a story with two past events that makes clear which one happened first. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"二つの過去の出来事について、どちらが先だったかを明確にする話について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Stretch","phrases":["I had already … when …","She had … before …","By the time …, …"],"vocabulary":["past perfect","sequence","before","timeline"]}]'::jsonb),
    ('august-02', '[{"key":"respectful-boundaries","title_en":"Respecting a personal boundary","title_ja":"個人的な境界線を尊重する","description_en":"How to ask a personal question politely and respond respectfully if the other person declines.","description_ja":"個人的な質問を丁寧に尋ね、相手が答えたくない時に境界線を尊重する方法","speaking_prompt_en":"Speak for 60–90 seconds about how to ask a personal question politely and respond respectfully if the other person declines. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"個人的な質問を丁寧に尋ね、相手が答えたくない時に境界線を尊重する方法について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about how to ask a personal question politely and respond respectfully if the other person declines. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"個人的な質問を丁寧に尋ね、相手が答えたくない時に境界線を尊重する方法について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["Do you mind if I ask …?","I’d rather not say.","I hope I didn’t offend you."],"vocabulary":["privacy","boundary","permission","respectful"]},{"key":"tell-apart","title_en":"How you recognise people or things","title_ja":"人や物を見分ける方法","description_en":"Clues you use to tell similar people or objects apart.","description_ja":"似ている人や物を見分けるために使う特徴や手がかり","speaking_prompt_en":"Speak for 60–90 seconds about clues you use to tell similar people or objects apart. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"似ている人や物を見分けるために使う特徴や手がかりについて60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about clues you use to tell similar people or objects apart. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"似ている人や物を見分けるために使う特徴や手がかりについて100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I can’t tell them apart.","I recognised … from …","Can you identify …?"],"vocabulary":["recognise","identify","feature","similar"]},{"key":"contrast-clearly","title_en":"A plan despite a problem","title_ja":"問題があっても進めた予定","description_en":"A plan you completed despite a difficulty, using both despite and although accurately.","description_ja":"困難があっても実行した予定を、despiteとalthoughを正確に使って説明すること","speaking_prompt_en":"Speak for 60–90 seconds about a plan you completed despite a difficulty, using both despite and although accurately. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"困難があっても実行した予定を、despiteとalthoughを正確に使って説明することについて60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a plan you completed despite a difficulty, using both despite and although accurately. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"困難があっても実行した予定を、despiteとalthoughを正確に使って説明することについて100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Stretch","phrases":["Despite …, we …","Although it was …, we …","Let me check and get back to you."],"vocabulary":["despite","although","contrast","schedule"]}]'::jsonb),
    ('august-03', '[{"key":"not-yet-today","title_en":"What is not finished yet","title_ja":"今日まだ終わっていないこと","description_en":"What you have already done today and what you have not done yet.","description_ja":"今日すでにしたことと、まだしていないこと","speaking_prompt_en":"Speak for 60–90 seconds about what you have already done today and what you have not done yet. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"今日すでにしたことと、まだしていないことについて60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about what you have already done today and what you have not done yet. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"今日すでにしたことと、まだしていないことについて100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I have already …","I haven’t … yet.","Have you … yet?"],"vocabulary":["already","yet","complete","routine"]},{"key":"first-experience","title_en":"Trying something for the first time","title_ja":"初めて試した経験","description_en":"Something you had never tried before and how your opinion changed after trying it.","description_ja":"以前は一度も試したことがなく、試した後に印象が変わったもの","speaking_prompt_en":"Speak for 60–90 seconds about something you had never tried before and how your opinion changed after trying it. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"以前は一度も試したことがなく、試した後に印象が変わったものについて60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about something you had never tried before and how your opinion changed after trying it. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"以前は一度も試したことがなく、試した後に印象が変わったものについて100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I have never tried … before.","I tried it …","It was an acquired taste."],"vocabulary":["experience","acquired taste","flavour","opinion"]},{"key":"three-time-frames","title_en":"One story, three time frames","title_ja":"三つの時制で話す出来事","description_en":"An everyday story that distinguishes a finished past event, an earlier past event and a regular habit.","description_ja":"終了した過去・それより前の過去・普段の習慣を区別する日常の話","speaking_prompt_en":"Speak for 60–90 seconds about an everyday story that distinguishes a finished past event, an earlier past event and a regular habit. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"終了した過去・それより前の過去・普段の習慣を区別する日常の話について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about an everyday story that distinguishes a finished past event, an earlier past event and a regular habit. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"終了した過去・それより前の過去・普段の習慣を区別する日常の話について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Stretch","phrases":["I … yesterday.","She had … before I …","I usually …"],"vocabulary":["simple past","past perfect","habit","sequence"]}]'::jsonb),
    ('august-09', '[{"key":"emotional-moment","title_en":"A moment that brought tears","title_ja":"涙が出た瞬間","description_en":"A film, story or real event that made you emotional and how strongly you reacted.","description_ja":"映画・物語・実際の出来事で感情が動き、どのように泣いたか","speaking_prompt_en":"Speak for 60–90 seconds about a film, story or real event that made you emotional and how strongly you reacted. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"映画・物語・実際の出来事で感情が動き、どのように泣いたかについて60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a film, story or real event that made you emotional and how strongly you reacted. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"映画・物語・実際の出来事で感情が動き、どのように泣いたかについて100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I shed a tear when …","I burst into tears.","It brought tears to my eyes."],"vocabulary":["tear","emotional","reaction","moving"]},{"key":"ordering-portions","title_en":"Ordering the right amount","title_ja":"適切な量を注文する","description_en":"How you would order drinks and food using natural counters and portion words.","description_ja":"飲み物や料理を、自然な数え方・量の表現で注文する方法","speaking_prompt_en":"Speak for 60–90 seconds about how you would order drinks and food using natural counters and portion words. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"飲み物や料理を、自然な数え方・量の表現で注文する方法について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about how you would order drinks and food using natural counters and portion words. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"飲み物や料理を、自然な数え方・量の表現で注文する方法について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["Could I have two …, please?","I’d like a glass of …","Would you like a piece of …?"],"vocabulary":["portion","glass","piece","countable"]},{"key":"spill-or-pour","title_en":"A table accident","title_ja":"食卓での小さな失敗","description_en":"A small accident with a drink and the difference between pouring it and spilling it.","description_ja":"飲み物を注ぐ行為と、誤ってこぼす行為の違いが分かる小さな出来事","speaking_prompt_en":"Speak for 60–90 seconds about a small accident with a drink and the difference between pouring it and spilling it. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"飲み物を注ぐ行為と、誤ってこぼす行為の違いが分かる小さな出来事について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a small accident with a drink and the difference between pouring it and spilling it. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"飲み物を注ぐ行為と、誤ってこぼす行為の違いが分かる小さな出来事について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Stretch","phrases":["I poured … into …","I accidentally spilled …","Let me clean it up."],"vocabulary":["pour","spill","liquid","accidentally"]}]'::jsonb),
    ('august-10-part-1', '[{"key":"kitchen-problem","title_en":"A fridge or freezer problem","title_ja":"冷蔵庫・冷凍庫のトラブル","description_en":"A kitchen appliance problem and the practical steps you would take to protect the food.","description_ja":"冷蔵庫や冷凍庫のトラブルと、食品を守るために取る対応","speaking_prompt_en":"Speak for 60–90 seconds about a kitchen appliance problem and the practical steps you would take to protect the food. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"冷蔵庫や冷凍庫のトラブルと、食品を守るために取る対応について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a kitchen appliance problem and the practical steps you would take to protect the food. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"冷蔵庫や冷凍庫のトラブルと、食品を守るために取る対応について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["The refrigerator isn’t working.","Please put … in the fridge.","The … is in the freezer."],"vocabulary":["fridge","freezer","appliance","temperature"]},{"key":"bad-connection","title_en":"When a call keeps cutting out","title_ja":"通話が何度も途切れるとき","description_en":"A difficult phone or video call where the sound repeatedly disappeared.","description_ja":"音声が何度も途切れた電話・ビデオ通話と、その時の状況","speaking_prompt_en":"Speak for 60–90 seconds about a difficult phone or video call where the sound repeatedly disappeared. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"音声が何度も途切れた電話・ビデオ通話と、その時の状況について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a difficult phone or video call where the sound repeatedly disappeared. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"音声が何度も途切れた電話・ビデオ通話と、その時の状況について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["The connection keeps cutting out.","You’re breaking up.","I couldn’t hear you clearly."],"vocabulary":["connection","signal","audio","interrupt"]},{"key":"repair-the-call","title_en":"Clarifying on a difficult call","title_ja":"聞き取れない通話を立て直す","description_en":"Polite clarification strategies that help both speakers complete a difficult call.","description_ja":"聞き取りにくい通話を最後まで進めるための丁寧な聞き返し方","speaking_prompt_en":"Speak for 60–90 seconds about polite clarification strategies that help both speakers complete a difficult call. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"聞き取りにくい通話を最後まで進めるための丁寧な聞き返し方について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about polite clarification strategies that help both speakers complete a difficult call. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"聞き取りにくい通話を最後まで進めるための丁寧な聞き返し方について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Stretch","phrases":["Could you say that again?","Could you speak more slowly?","Let me reconnect and call you back."],"vocabulary":["clarify","repeat","reconnect","slowly"]}]'::jsonb),
    ('august-10-part-2', '[{"key":"coffee-profile","title_en":"Your ideal coffee","title_ja":"理想のコーヒー","description_en":"Your preferred coffee flavour and how you would compare it with a roast you dislike.","description_ja":"好きなコーヒーの風味と、苦手な焙煎との具体的な比較","speaking_prompt_en":"Speak for 60–90 seconds about your preferred coffee flavour and how you would compare it with a roast you dislike. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"好きなコーヒーの風味と、苦手な焙煎との具体的な比較について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about your preferred coffee flavour and how you would compare it with a roast you dislike. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"好きなコーヒーの風味と、苦手な焙煎との具体的な比較について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I prefer mild coffee.","This blend is smooth and rich.","It tastes a little …"],"vocabulary":["mild","bitter","smooth","roast"]},{"key":"first-trip","title_en":"A first trip abroad","title_ja":"初めて訪れる国への旅行","description_en":"A country you have never visited and what you would like to experience there.","description_ja":"まだ訪れたことのない国と、そこで初めて体験したいこと","speaking_prompt_en":"Speak for 60–90 seconds about a country you have never visited and what you would like to experience there. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"まだ訪れたことのない国と、そこで初めて体験したいことについて60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a country you have never visited and what you would like to experience there. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"まだ訪れたことのない国と、そこで初めて体験したいことについて100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I’ve never been to …","It will be my first time in …","I’d like to visit …"],"vocabulary":["destination","experience","first time","someday"]},{"key":"decide-and-book","title_en":"From comparing to booking","title_ja":"比較から予約まで","description_en":"A travel decision you have not made yet and what will help you make it.","description_ja":"まだ決めていない旅行計画と、決断するために比較していること","speaking_prompt_en":"Speak for 60–90 seconds about a travel decision you have not made yet and what will help you make it. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"まだ決めていない旅行計画と、決断するために比較していることについて60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a travel decision you have not made yet and what will help you make it. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"まだ決めていない旅行計画と、決断するために比較していることについて100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Stretch","phrases":["I haven’t decided … yet.","I’m still comparing …","Once I decide, I’ll …"],"vocabulary":["compare","decide","flight","book"]}]'::jsonb),
    ('august-16-part-1', '[{"key":"permission-boundary","title_en":"When someone did not ask","title_ja":"断りなくされたこと","description_en":"A situation where someone used or took something without asking and how you responded.","description_ja":"誰かが断りなく物を使った・取った場面と、その時の伝え方","speaking_prompt_en":"Speak for 60–90 seconds about a situation where someone used or took something without asking and how you responded. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"誰かが断りなく物を使った・取った場面と、その時の伝え方について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a situation where someone used or took something without asking and how you responded. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"誰かが断りなく物を使った・取った場面と、その時の伝え方について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["He used … without asking.","Please don’t just help yourself to …","Next time, could you ask first?"],"vocabulary":["permission","boundary","belonging","respect"]},{"key":"weekend-tasks","title_en":"Sharing weekend tasks","title_ja":"週末の用事を分担する","description_en":"How you would organise a barbecue, shopping and household tasks with other people.","description_ja":"バーベキュー・買い物・家事を周りの人と分担する方法","speaking_prompt_en":"Speak for 60–90 seconds about how you would organise a barbecue, shopping and household tasks with other people. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"バーベキュー・買い物・家事を周りの人と分担する方法について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about how you would organise a barbecue, shopping and household tasks with other people. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"バーベキュー・買い物・家事を周りの人と分担する方法について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["We’re having a barbecue …","Could you do the dishes?","I need to do some shopping."],"vocabulary":["barbecue",