    ('august-23', '[{"key":"workday-thanks","title_en":"Ending the workday well","title_ja":"気持ちよく仕事を終える","description_en":"How you thank a colleague for a specific task and say goodbye at the end of the day.","description_ja":"同僚の具体的な仕事に感謝し、一日の終わりに自然に挨拶する方法","speaking_prompt_en":"Speak for 60–90 seconds about how you thank a colleague for a specific task and say goodbye at the end of the day. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"同僚の具体的な仕事に感謝し、一日の終わりに自然に挨拶する方法について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about how you thank a colleague for a specific task and say goodbye at the end of the day. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"同僚の具体的な仕事に感謝し、一日の終わりに自然に挨拶する方法について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["Thanks for your hard work today.","Thanks for taking care of that.","Have a good evening."],"vocabulary":["colleague","appreciation","task","evening"]},{"key":"clear-schedule","title_en":"Clearing up a schedule mix-up","title_ja":"予定の行き違いを解消する","description_en":"A confusing set of instructions or schedule and the questions you would ask to clarify it.","description_ja":"分かりにくい説明や予定について、確認の質問で行き違いを解消すること","speaking_prompt_en":"Speak for 60–90 seconds about a confusing set of instructions or schedule and the questions you would ask to clarify it. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"分かりにくい説明や予定について、確認の質問で行き違いを解消することについて60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a confusing set of instructions or schedule and the questions you would ask to clarify it. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"分かりにくい説明や予定について、確認の質問で行き違いを解消することについて100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["What time does … open?","What time will … start?","There seems to be some confusion."],"vocabulary":["schedule","instructions","confused","clarify"]},{"key":"suspicious-message","title_en":"A message that feels off","title_ja":"違和感のあるメッセージ","description_en":"A suspicious message or offer, the warning signs you noticed and the safe action you took.","description_ja":"怪しいメッセージ・提案で気づいた警告サインと、安全のために取った行動","speaking_prompt_en":"Speak for 60–90 seconds about a suspicious message or offer, the warning signs you noticed and the safe action you took. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"怪しいメッセージ・提案で気づいた警告サインと、安全のために取った行動について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a suspicious message or offer, the warning signs you noticed and the safe action you took. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"怪しいメッセージ・提案で気づいた警告サインと、安全のために取った行動について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Stretch","phrases":["That message looks suspicious.","Something feels off.","This … sounds fishy."],"vocabulary":["suspicious","fishy","warning sign","verify"]}]'::jsonb),
    ('august-24', '[{"key":"dumpling-guide","title_en":"Explaining your favourite dumpling","title_ja":"好きな点心を説明する","description_en":"A dumpling dish you would recommend, including its filling, cooking method and texture.","description_ja":"おすすめの点心について、具・調理法・食感を含めて説明すること","speaking_prompt_en":"Speak for 60–90 seconds about a dumpling dish you would recommend, including its filling, cooking method and texture. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"おすすめの点心について、具・調理法・食感を含めて説明することについて60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a dumpling dish you would recommend, including its filling, cooking method and texture. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"おすすめの点心について、具・調理法・食感を含めて説明することについて100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["… are …-style dumplings.","They are filled with …","They are … until crispy."],"vocabulary":["dumpling","filling","steamed","crispy"]},{"key":"both-of-us","title_en":"Something you both enjoy","title_ja":"二人とも楽しめること","description_en":"An activity or meal two people both enjoy, using both in several natural sentence positions.","description_ja":"二人とも楽しめる活動・食事を、bothの異なる自然な位置で説明すること","speaking_prompt_en":"Speak for 60–90 seconds about an activity or meal two people both enjoy, using both in several natural sentence positions. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"二人とも楽しめる活動・食事を、bothの異なる自然な位置で説明することについて60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about an activity or meal two people both enjoy, using both in several natural sentence positions. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"二人とも楽しめる活動・食事を、bothの異なる自然な位置で説明することについて100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["We both like …","We are both …","Both … look …"],"vocabulary":["both","agreement","shared","preference"]},{"key":"rule-and-question","title_en":"A rule explained politely","title_ja":"ルールを丁寧に確認する","description_en":"A strong rule and a polite indirect question that helps someone follow it.","description_ja":"強い禁止事項と、それを守るために使う丁寧な間接疑問文","speaking_prompt_en":"Speak for 60–90 seconds about a strong rule and a polite indirect question that helps someone follow it. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"強い禁止事項と、それを守るために使う丁寧な間接疑問文について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a strong rule and a polite indirect question that helps someone follow it. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"強い禁止事項と、それを守るために使う丁寧な間接疑問文について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Stretch","phrases":["You must not …","Do you know where … is?","Can you tell me what … means?"],"vocabulary":["prohibition","indirect question","word order","polite"]}]'::jsonb),
    ('august-25', '[{"key":"welcome-back","title_en":"Coming home and welcoming someone","title_ja":"帰宅とお迎えの挨拶","description_en":"A natural exchange when one person returns home or comes back to a familiar place.","description_ja":"家や元いた場所に戻った人と迎える人の自然なやり取り","speaking_prompt_en":"Speak for 60–90 seconds about a natural exchange when one person returns home or comes back to a familiar place. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"家や元いた場所に戻った人と迎える人の自然なやり取りについて60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a natural exchange when one person returns home or comes back to a familiar place. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"家や元いた場所に戻った人と迎える人の自然なやり取りについて100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I’m home!","I’m back.","Welcome back!"],"vocabulary":["return","welcome","home","familiar"]},{"key":"heading-out","title_en":"Saying goodbye as you head out","title_ja":"外出時の自然な挨拶","description_en":"A short conversation when someone leaves for work or a fun activity.","description_ja":"仕事や楽しい予定へ出かける人との短い会話","speaking_prompt_en":"Speak for 60–90 seconds about a short conversation when someone leaves for work or a fun activity. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"仕事や楽しい予定へ出かける人との短い会話について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a short conversation when someone leaves for work or a fun activity. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"仕事や楽しい予定へ出かける人との短い会話について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Core","phrases":["I’m heading out now.","Take care!","Have fun!"],"vocabulary":["head out","destination","send-off","safely"]},{"key":"pour-or-poor","title_en":"Clear pronunciation in context","title_ja":"文脈で区別するpourとpoor","description_en":"A short situation that makes the meanings of pour and poor clear through context and pronunciation.","description_ja":"pourとpoorの意味を、文脈と発音から明確に区別できる短い場面","speaking_prompt_en":"Speak for 60–90 seconds about a short situation that makes the meanings of pour and poor clear through context and pronunciation. Give one concrete example and explain why it matters to you.","speaking_prompt_ja":"pourとpoorの意味を、文脈と発音から明確に区別できる短い場面について60〜90秒で話してください。具体例を1つ挙げ、自分にとってなぜ大切かも説明しましょう。","essay_prompt_en":"Write 100–180 words about a short situation that makes the meanings of pour and poor clear through context and pronunciation. Give a clear reason, one supporting example and a final takeaway.","essay_prompt_ja":"pourとpoorの意味を、文脈と発音から明確に区別できる短い場面について100〜180語で書いてください。理由・具体例・最後のまとめを入れましょう。","challenge":"Stretch","phrases":["Please pour … slowly.","The poor …","The context tells us …"],"vocabulary":["pour","poor","pronunciation","context"]}]'::jsonb)
),
author as (
  select user_id
  from public.review_teachers
  where active
  order by created_at, user_id
  limit 1
),
prepared as (
  select
    l.id as lesson_id,
    l.title_en,
    l.title_ja,
    source.slug,
    source.topics,
    author.user_id as teacher_id
  from source
  join public.review_lessons l on l.slug = source.slug
  cross join author
),
tasks as (
  select
    p.lesson_id,
    p.slug || '-premium-speaking-v1' as stable_key,
    'speaking'::text as task_type,
    'Speaking review · ' || p.title_en as title_en,
    'スピーキング添削 · ' || coalesce(p.title_ja, p.title_en) as title_ja,
    'Choose one of the three lesson topics and record a 60–90 second response. Give one concrete example, use the recommended language naturally and explain why the idea matters to you.' as prompt_en,
    '3つのレッスントピックから1つ選び、60〜90秒で録音してください。具体例を1つ挙げ、おすすめ表現を自然に使い、自分にとってなぜ大切かも説明しましょう。' as prompt_ja,
    'Plan briefly, record once, listen back, then re-record if needed before submitting.' as instructions_en,
    '短く内容を考えて録音し、聞き直してから必要に応じて録り直して提出してください。' as instructions_ja,
    coalesce(p.topics -> 0 -> 'phrases', '[]'::jsonb) as required_phrases,
    coalesce(p.topics -> 0 -> 'vocabulary', '[]'::jsonb) as required_vocabulary,
    90::integer as target_seconds,
    null::integer as min_word_count,
    null::integer as max_word_count,
    3::integer as max_attempts,
    true as active,
    p.teacher_id as created_by,
    p.topics
  from prepared p

  union all

  select
    p.lesson_id,
    p.slug || '-premium-essay-v1',
    'essay'::text,
    'Writing review · ' || p.title_en,
    '英作文添削 · ' || coalesce(p.title_ja, p.title_en),
    'Choose one of the three lesson topics and write 100–180 words. Give a clear reason, one supporting example and a final takeaway while using the recommended language naturally.',
    '3つのレッスントピックから1つ選び、100〜180語で書いてください。おすすめ表現を自然に使い、理由・具体例・最後のまとめを入れましょう。',
    'Write a clear beginning, supporting detail and final sentence. Check grammar, word choice and verb tense before submitting.',
    '導入・具体的な説明・最後の一文を入れ、提出前に文法・語彙・動詞の時制を確認してください。',
    coalesce(p.topics -> 0 -> 'phrases', '[]'::jsonb),
    coalesce(p.topics -> 0 -> 'vocabulary', '[]'::jsonb),
    null::integer,
    100::integer,
    180::integer,
    3::integer,
    true,
    p.teacher_id,
    p.topics
  from prepared p
)
insert into public.review_premium_tasks (
  lesson_id, stable_key, task_type, title_en, title_ja,
  prompt_en, prompt_ja, instructions_en, instructions_ja,
  required_phrases, required_vocabulary, target_seconds,
  min_word_count, max_word_count, max_attempts, active, created_by, topics
)
select
  lesson_id, stable_key, task_type, title_en, title_ja,
  prompt_en, prompt_ja, instructions_en, instructions_ja,
  required_phrases, required_vocabulary, target_seconds,
  min_word_count, max_word_count, max_attempts, active, created_by, topics
from tasks
on conflict (lesson_id, stable_key) do update set
  task_type = excluded.task_type,
  title_en = excluded.title_en,
  title_ja = excluded.title_ja,
  prompt_en = excluded.prompt_en,
  prompt_ja = excluded.prompt_ja,
  instructions_en = excluded.instructions_en,
  instructions_ja = excluded.instructions_ja,
  required_phrases = excluded.required_phrases,
  required_vocabulary = excluded.required_vocabulary,
  target_seconds = excluded.target_seconds,
  min_word_count = excluded.min_word_count,
  max_word_count = excluded.max_word_count,
  max_attempts = excluded.max_attempts,
  active = true,
  topics = excluded.topics,
  updated_at = now();

do $verify$
declare
  seeded_count integer;
  speaking_count integer;
  essay_count integer;
  topic_count integer;
  invalid_topic_count integer;
  invalid_task_count integer;
begin
  select
    count(*),
    count(*) filter (where t.task_type = 'speaking'),
    count(*) filter (where t.task_type = 'essay'),
    coalesce(sum(jsonb_array_length(t.topics)), 0)
  into seeded_count, speaking_count, essay_count, topic_count
  from public.review_premium_tasks t
  join public.review_lessons l on l.id = t.lesson_id
  where t.active
    and l.slug in ('july-30-part-1', 'july-30-part-2', 'august-02', 'august-03', 'august-09', 'august-10-part-1', 'august-10-part-2', 'august-16-part-1', 'august-16-part-2', 'august-17-part-1', 'august-17-part-2', 'august-23', 'august-24', 'august-25')
    and t.stable_key in (
      l.slug || '-premium-speaking-v1',
      l.slug || '-premium-essay-v1'
    );

  select count(*) into invalid_topic_count
  from public.review_premium_tasks t
  join public.review_lessons l on l.id = t.lesson_id
  cross join lateral jsonb_array_elements(t.topics) item
  where t.active
    and l.slug in ('july-30-part-1', 'july-30-part-2', 'august-02', 'august-03', 'august-09', 'august-10-part-1', 'august-10-part-2', 'august-16-part-1', 'august-16-part-2', 'august-17-part-1', 'august-17-part-2', 'august-23', 'august-24', 'august-25')
    and t.stable_key in (
      l.slug || '-premium-speaking-v1',
      l.slug || '-premium-essay-v1'
    )
    and (
      jsonb_typeof(item) <> 'object'
      or nullif(btrim(item ->> 'key'), '') is null
      or nullif(btrim(item ->> 'title_en'), '') is null
      or nullif(btrim(item ->> 'title_ja'), '') is null
      or nullif(btrim(item ->> 'description_en'), '') is null
      or nullif(btrim(item ->> 'description_ja'), '') is null
      or nullif(btrim(item ->> 'speaking_prompt_en'), '') is null
      or nullif(btrim(item ->> 'speaking_prompt_ja'), '') is null
      or nullif(btrim(item ->> 'essay_prompt_en'), '') is null
      or nullif(btrim(item ->> 'essay_prompt_ja'), '') is null
      or jsonb_typeof(item -> 'phrases') <> 'array'
      or jsonb_array_length(item -> 'phrases') not between 3 and 6
      or jsonb_typeof(item -> 'vocabulary') <> 'array'
      or jsonb_array_length(item -> 'vocabulary') not between 3 and 8
    );

  select count(*) into invalid_task_count
  from public.review_premium_tasks t
  join public.review_lessons l on l.id = t.lesson_id
  where t.active
    and l.slug in ('july-30-part-1', 'july-30-part-2', 'august-02', 'august-03', 'august-09', 'august-10-part-1', 'august-10-part-2', 'august-16-part-1', 'august-16-part-2', 'august-17-part-1', 'august-17-part-2', 'august-23', 'august-24', 'august-25')
    and t.stable_key in (
      l.slug || '-premium-speaking-v1',
      l.slug || '-premium-essay-v1'
    )
    and (
      jsonb_array_length(t.topics) <> 3
      or (select count(distinct item ->> 'key') from jsonb_array_elements(t.topics) item) <> 3
      or (t.task_type = 'speaking' and (t.target_seconds <> 90 or t.min_word_count is not null or t.max_word_count is not null))
      or (t.task_type = 'essay' and (t.target_seconds is not null or t.min_word_count <> 100 or t.max_word_count <> 180))
    );

  if seeded_count <> 28
     or speaking_count <> 14
     or essay_count <> 14
     or topic_count <> 84
     or invalid_topic_count <> 0
     or invalid_task_count <> 0 then
    raise exception 'New Premium task verification failed: tasks %, speaking %, essay %, topic rows %, invalid topics %, invalid tasks %.',
      seeded_count, speaking_count, essay_count, topic_count, invalid_topic_count, invalid_task_count;
  end if;
end;
$verify$;

comment on column public.review_premium_tasks.topics is
  'Learner-safe bilingual topic choices with topic-specific prompts, phrases and vocabulary.';
